#include "offline_media.hpp"
#include "owner_state.hpp"
#include <iostream>
namespace ow::win {void headless_bootstrap_acceptance(const std::filesystem::path&,const std::string&,const std::string&);}
int wmain(int argc,wchar_t** argv){using namespace ow;using namespace ow::win;try{if(argc!=5)throw std::runtime_error("Usage: isolated-unattended-fixture NEW_ROOT APPROVED_FFMPEG SHA256 PUBLIC_ENROLLMENT_ID");require_normal_owner();USEROBJECTFLAGS station{};DWORD needed{};require(GetUserObjectInformationW(GetProcessWindowStation(),UOI_FLAGS,&station,sizeof(station),&needed),"Read ACTUAL fixture station");if(station.dwFlags&WSF_VISIBLE)throw std::runtime_error("Synthetic unattended fixture must run on an actual noninteractive station, not a fabricated session number");Config c;c.root=argv[1];c.ffmpeg=argv[2];c.ffmpeg_sha256=utf8(argv[3]);const auto report_path=c.root/"acceptance-result.json";headless_bootstrap_acceptance(c.ffmpeg,c.ffmpeg_sha256,utf8(argv[4]));auto result=OfflineMediaHarness::control_acceptance(std::move(c),true);result["actual_bootstrap_verified"]=true;result["protected_bootstrap_verified"]=true;result["caller_independent_wrapper_restart"]=true;result["noninteractive_window_station"]=true;result["password_task_registration"]=false;atomic_write(report_path,json::serialize(result));std::cout<<json::serialize(result)<<"\n";return 0;}catch(const std::exception& e){try{if(argc==5)atomic_write(std::filesystem::path(std::wstring(argv[1])+L".fixture-failure.txt"),e.what());}catch(...){}std::cerr<<"UNATTENDED_FIXTURE_REJECTED: "<<e.what()<<"\n";return 1;}}
